"""Owner-requested issue split. Preserve every created URL before continuing."""
import json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];DATA=ROOT/'runs/experiments/data/run-exp-strategic-fleet'
receipt=DATA/'issue-creation-v1.jsonl'
if receipt.exists():raise RuntimeError('Inspect existing issue receipts before any retry')
source='https://github.com/diegoami/ic2-conquest/blob/363a9069089bd400c6905f3b93975162395031b3/findings/2026-10-24-strategic-fidelity-pilot171.md'
common=f'Evidence: {source} and conquest #171. Owner requested issues for the corrections and remaining strategic research, and continued investigation on 2026-10-24.\n\nNever delete/overwrite measurements or saves; unique labels, tracked text/hashes, approved binary storage, commit/push each batch/30min. Owner1355/1388 files/hashes stay private; no other repository source edit or native Computer Use restart. Distinguish matched local decisions from unmatched whole-turn histories and intentional remake policies.\n'
tasks=[
('resupply','diegoami/imperial_conquest_2','Faithful strategic AI: correct resupply-city threshold, stock eligibility and capital preference',
 'The eleven-scenario pilot isolates a raw destination-selector difference using six same-input original-instruction controls. Original FUN0044E670 uses floor(troops/1000), accepts own stock ABOVE that threshold and favors a capital by minimizing distance minus20. Current55d96876 uses /100, stock BELOW threshold and a capital penalty in its maximized negative-distance score. Automatic transfer quantities are a separate rule.\n\nAcceptance: preserve six swapped-capital/stock29,30,297,298 controls (including positive matches); verify the112retained decision states and selected/resolved destinations separately; correct rule/provenance data after Research corrects/promotes section3.3; retain intentional reachable-resupply policy separately rather than silently changing it; run appropriate AI/movement/solution/CI gates. No combat coefficients or save-schema change. Coordinates and unit values are fixtures, not production constants. Research intake is pending; this is a concrete implementation task, not accepted production fidelity.'),
('fleet','diegoami/ic2-conquest','Strategic fidelity: matched fleet hunt, port and stored-destination decisions',
 'Continue #171 with matched original/native fleet decisions. Declare controls for peace versus war, stronger/farther and weaker/nearer enemies, own-port protection, hunt score100/101, port stock/money thresholds, stored destinations, cargo and blocked sea routes. Start with retained generated snapshots and original instructions; conditional decisions outside the original fleet phase must be labelled synthetic controls. Verify model inputs, preserve CPU/RNG state and distinguish proposals from accepted commands. Then use guarded actual fleet-boundary observations as needed. Deliver exact decision ledger, classifications and bounded findings; no production fix implied. This is the next active research batch.'),
('homeland','diegoami/ic2-conquest','Strategic fidelity: matched homeland threat and defender dispatch decisions',
 'Capture FUN0044EFC8 threat-list/responder boundaries and native equivalents. Cover region/coast membership, war versus peace, capital radii, troops aboard fleets, already-committed armies, responder cap and record order. Use the retained threat-case observed Seleucid dispatch as anchor. Separate target-tree choices from the earlier homeland dispatch. Deliver same-input first-difference controls and identify deliberate policy changes before reporting defects.'),
('economy','diegoami/ic2-conquest','Strategic fidelity: economic budgets, recruitment and automatic supply decisions',
 'Compare original and native economic phase inputs and decisions: threat budget, treasury/reserve gates, recruit/mobilize choices and amounts, tax timing, consolidation/disbanding, automatic supply/purse and mercenary hires. Capture pre/post phase states and actual random bounds/results; do not infer defects from the pilot\'s different terminal resources. Include healthy/depleted cases and own/foreign providers; keep destination scoring separate from transfer quantity. Deliver decision/RNG ledger and minimal controls.'),
('diplomacy','diegoami/ic2-conquest','Strategic fidelity: diplomatic candidates, random gates and action order',
 'Compare original/native war declarations, trade formation/swaps, alliances and peace offers using exact candidates, score/ranking, eligibility and random bounds/results. Preserve cooldown/neighbor/human-seat gates and phase order. The same seed number does not align named native streams with original global RNG. Instrument actual original decision boundaries; validate conditional counterfactuals before longer-turn claims. Human replies must be explicit and recorded.'),
('campaign','diegoami/ic2-conquest','Strategic fidelity: all sixteen starts and short campaign regression matrix',
 'Expand the pilot after the identified eligibility/routing and resupply differences are reconciled, so a known first-turn divergence does not obscure every later comparison. Cover all16starts and predeclared3-5turn continuations across terrain, seasons, resources and war states. Retain first-divergence evidence and distinguish original/native random histories. Depends on the correction tasks and coverage from the fleet/homeland/economy/diplomacy studies. No automatic strategy run or paused battle-queue resumption.')]
for key,repo,title,body in tasks:
    path=DATA/(key+'-issue-body-v1.md')
    with path.open('x') as f:f.write(body+'\n\n'+common)
    run=subprocess.run(['gh','issue','create','--repo',repo,'--title',title,'--body-file',str(path)],text=True,capture_output=True)
    with receipt.open('a') as f:f.write(json.dumps(dict(key=key,repo=repo,title=title,returncode=run.returncode,url=run.stdout.strip(),error=run.stderr))+'\n')
    if run.returncode:raise SystemExit(run.stderr)
    print(key,run.stdout.strip(),flush=True)
